files.content:
[hidden] { display: none !important; }

:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #e94560;
  --secondary: #0f3460;
  --text: #f0f0f0;
  --accent: #f9c74f;
  --font-pixel: 'Courier New', Courier, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  background-image: repeating-linear-gradient(0deg, transparent, transparent 2px, rgba(255,255,255,0.03) 2px, rgba(255,255,255,0.03) 4px);
  font-family: var(--font-pixel);
  font-size: 16px;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border: 4px solid var(--primary);
  padding: 32px 24px;
  max-width: 480px;
  width: 100%;
  text-align: center;
  box-shadow: 8px 8px 0 var(--secondary);
  image-rendering: pixelated;
}

h1 {
  font-size: 1.5rem;
  color: var(--primary);
  letter-spacing: 2px;
  margin-bottom: 16px;
  text-shadow: 2px 2px 0 var(--secondary);
}

.mode-indicator {
  font-size: 1rem;
  color: var(--accent);
  letter-spacing: 4px;
  margin-bottom: 8px;
  text-transform: uppercase;
}

.timer {
  font-size: 5rem;
  font-weight: bold;
  color: var(--text);
  line-height: 1.1;
  margin: 16px 0 24px;
  letter-spacing: 4px;
  text-shadow: 4px 4px 0 var(--secondary);
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  margin-bottom: 16px;
}

.mode-switch {
  display: flex;
  gap: 12px;
  justify-content: center;
}

.pixel-btn {
  font-family: var(--font-pixel);
  font-size: 1rem;
  padding: 12px 20px;
  background: var(--secondary);
  color: var(--text);
  border: 3px solid var(--primary);
  cursor: pointer;
  letter-spacing: 1px;
  transition: background 0.1s, transform 0.05s, box-shadow 0.1s;
  box-shadow: 3px 3px 0 #000;
  min-width: 100px;
}

.pixel-btn:hover {
  background: var(--primary);
  color: var(--bg);
}

.pixel-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.pixel-btn:active {
  transform: translate(3px, 3px);
  box-shadow: none;
}

.mode-btn.active {
  background: var(--primary);
  color: var(--bg);
}

@media (max-width: 400px) {
  .timer {
    font-size: 3.5rem;
  }
  .pixel-btn {
    font-size: 0.9rem;
    padding: 10px 14px;
    min-width: 80px;
  }
  .card {
    padding: 24px 16px;
  }
}

const WORK_TIME = 25 * 60;
const BREAK_TIME = 5 * 60;

const timerEl = document.getElementById('timer');
const modeIndicator = document.getElementById('mode-indicator');
const startPauseBtn = document.getElementById('start-pause');
const resetBtn = document.getElementById('reset');
const workModeBtn = document.getElementById('work-mode');
const breakModeBtn = document.getElementById('break-mode');

let currentMode = 'work';
let remainingSeconds = WORK_TIME;
let isRunning = false;
let intervalId = null;
let endTime = null;

function formatTime(seconds) {
  const m = Math.floor(seconds / 60).toString().padStart(2, '0');
  const s = (seconds % 60).toString().padStart(2, '0');
  return `${m}:${s}`;
}

function updateDisplay() {
  timerEl.textContent = formatTime(remainingSeconds);
  modeIndicator.textContent = currentMode === 'work' ? 'WORK' : 'BREAK';
}

function setMode(mode) {
  stopTimer();
  currentMode = mode;
  remainingSeconds = mode === 'work' ? WORK_TIME : BREAK_TIME;
  updateDisplay();
  workModeBtn.classList.toggle('active', mode === 'work');
  breakModeBtn.classList.toggle('active', mode === 'break');
  workModeBtn.setAttribute('aria-pressed', mode === 'work');
  breakModeBtn.setAttribute('aria-pressed', mode === 'break');
}

function startTimer() {
  if (isRunning) return;
  isRunning = true;
  startPauseBtn.textContent = 'PAUSE';
  startPauseBtn.setAttribute('aria-label', 'Pause timer');
  endTime = Date.now() + remainingSeconds * 1000;
  intervalId = setInterval(tick, 250);
}

function stopTimer() {
  if (!isRunning) return;
  isRunning = false;
  clearInterval(intervalId);
  intervalId = null;
  startPauseBtn.textContent = 'START';
  startPauseBtn.setAttribute('aria-label', 'Start timer');
}

function tick() {
  const now = Date.now();
  const diff = Math.max(0, Math.round((endTime - now) / 1000));
  if (diff !== remainingSeconds) {
    remainingSeconds = diff;
    updateDisplay();
  }
  if (remainingSeconds <= 0) {
    stopTimer();
    // Auto-switch mode on completion
    setMode(currentMode === 'work' ? 'break' : 'work');
  }
}

function resetTimer() {
  stopTimer();
  remainingSeconds = currentMode === 'work' ? WORK_TIME : BREAK_TIME;
  updateDisplay();
}

startPauseBtn.addEventListener('click', () => {
  if (isRunning) {
    stopTimer();
  } else {
    startTimer();
  }
});

resetBtn.addEventListener('click', resetTimer);
workModeBtn.addEventListener('click', () => setMode('work'));
breakModeBtn.addEventListener('click', () => setMode('break'));

// Initialize
updateDisplay();
